const raw = $input.first().json;
const body = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;
const event = String(body.event || '');
const channels = body.channelsConfig || {};

const b64 = obj => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');

if (event !== 'discord.slash_command') {
  throw new Error(`Evento não suportado no workflow Usami Principal: ${event}`);
}

const cmd = String(body.commandName || '');
const opts = body.options || {};
const user = body.user || {};
const guildId = String(body.guildId || 'dm');
const channelId = String(body.channelId || '');
const userId = String(user.id || '');
const username = String(user.globalName || user.username || 'usuário');
const webhookPatchUrl = body.webhookPatchUrl || '';

// Apenas processa o comando 'usami'
if (cmd !== 'usami') {
  throw new Error(`Comando não é /usami: ${cmd}`);
}

const sub = String(opts.subcomando || opts.subcommand || '');

// 1. Subcomando: chat
if (sub === 'chat') {
  const mensagem = String(opts.mensagem || '').trim().slice(0, 1800);
  const criarThread = Boolean(opts.thread);
  if (!mensagem) {
    return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'chat', body, channels, sql: '', payloadB64: '', error: 'Mensagem é obrigatória para /usami chat', webhookPatchUrl } }];
  }
  // Encaminha para o workflow de chat existente via webhook interno
  // Aqui apenas registramos a interação e retornamos sucesso
  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
    st AS (
      INSERT INTO discord_server_stats (guild_id, commands_count, updated_at)
      SELECT p.j->>'guildId', 1, NOW() FROM p
      ON CONFLICT (guild_id) DO UPDATE SET commands_count = discord_server_stats.commands_count + 1, updated_at = NOW()
    ),
    ins AS (
      INSERT INTO usami_chat_log (guild_id, user_id, username, message, thread_created)
      SELECT p.j->>'guildId', p.j->>'userId', p.j->>'username', p.j->>'mensagem', (p.j->>'criarThread')::bool FROM p
      RETURNING id, created_at
    )
    SELECT jsonb_build_object(
      'action', 'chat',
      'logged', (SELECT row_to_json(ins) FROM ins LIMIT 1),
      'webhookPatchUrl', (SELECT p.j->>'webhookPatchUrl' FROM p)
    ) AS result;
  `;
  const payload = { guildId, userId, username, mensagem, criarThread, webhookPatchUrl };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'chat', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

// 2. Subcomando: status
if (sub === 'status') {
  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j)
    SELECT jsonb_build_object(
      'action', 'status',
      'server', (SELECT row_to_json(s) FROM discord_server_stats s WHERE s.guild_id = (SELECT p.j->>'guildId' FROM p)),
      'mood', (SELECT row_to_json(m) FROM usami_mood m WHERE m.guild_id = (SELECT p.j->>'guildId' FROM p) ORDER BY m.updated_at DESC LIMIT 1),
      'affinity', (SELECT row_to_json(a) FROM usami_affinity a WHERE a.guild_id = (SELECT p.j->>'guildId' FROM p) ORDER BY a.updated_at DESC LIMIT 1),
      'sleepMode', (SELECT row_to_json(s) FROM usami_sleep_mode s WHERE s.guild_id = (SELECT p.j->>'guildId' FROM p) AND s.active = TRUE LIMIT 1),
      'presence', (SELECT jsonb_build_object(
        'state', COALESCE(rp.state, 'idle'),
        'details', COALESCE(rp.details, ''),
        'largeImage', COALESCE(rp.large_image_key, ''),
        'largeText', COALESCE(rp.large_image_text, ''),
        'smallImage', COALESCE(rp.small_image_key, ''),
        'smallText', COALESCE(rp.small_image_text, ''),
        'startTimestamp', rp.start_timestamp,
        'endTimestamp', rp.end_timestamp
      ) FROM usami_rich_presence rp WHERE rp.guild_id = (SELECT p.j->>'guildId' FROM p) ORDER BY rp.updated_at DESC LIMIT 1)
    ) AS result;
  `;
  const payload = { guildId };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'status', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

// 3. Subcomando: memoria
if (sub === 'memoria') {
  const acao = String(opts.acao || 'ver');
  const chave = String(opts.chave || '').trim();

  if (acao === 'limpar' && !chave) {
    return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'memoria', body, channels, sql: '', payloadB64: '', error: 'Chave é obrigatória para limpar memória', webhookPatchUrl } }];
  }

  let sql = '';
  if (acao === 'ver') {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      rows AS (
        SELECT key, value, created_at, updated_at
        FROM usami_memory
        WHERE guild_id = (SELECT p.j->>'guildId' FROM p)
          AND (p.j->>'chave' IS NULL OR p.j->>'chave' = '' OR key = (SELECT p.j->>'chave' FROM p))
        ORDER BY updated_at DESC LIMIT 20
      )
      SELECT jsonb_build_object(
        'action', 'memoria_ver',
        'memories', COALESCE((SELECT jsonb_agg(row_to_json(rows)) FROM rows), '[]'::jsonb)
      ) AS result;
    `;
  } else {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      del AS (
        DELETE FROM usami_memory
        WHERE guild_id = (SELECT p.j->>'guildId' FROM p)
          AND key = (SELECT p.j->>'chave' FROM p)
        RETURNING key, value
      )
      SELECT jsonb_build_object(
        'action', 'memoria_limpar',
        'deleted', COALESCE((SELECT jsonb_agg(row_to_json(del)) FROM del), '[]'::jsonb)
      ) AS result;
    `;
  }
  const payload = { guildId, userId, acao, chave };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'memoria', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

// 4. Subcomando: humor
if (sub === 'humor') {
  const acao = String(opts.acao || 'ver');
  const humor = String(opts.humor || '').trim();
  const validMoods = ['happy', 'tsundere', 'surprised', 'thinking', 'neutral', 'sad', 'angry'];

  if (acao === 'definir' && !validMoods.includes(humor)) {
    return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'humor', body, channels, sql: '', payloadB64: '', error: 'Humor inválido. Use: ' + validMoods.join(', '), webhookPatchUrl } }];
  }

  let sql = '';
  if (acao === 'ver') {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j)
      SELECT jsonb_build_object(
        'action', 'humor_ver',
        'current', (SELECT row_to_json(m) FROM usami_mood m WHERE m.guild_id = (SELECT p.j->>'guildId' FROM p) ORDER BY m.updated_at DESC LIMIT 1)
      ) AS result;
    `;
  } else {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      up AS (
        INSERT INTO usami_mood (guild_id, mood, set_by_user_id, set_by_username)
        SELECT p.j->>'guildId', p.j->>'humor', p.j->>'userId', p.j->>'username' FROM p
        ON CONFLICT (guild_id) DO UPDATE SET
          mood = EXCLUDED.mood,
          set_by_user_id = EXCLUDED.set_by_user_id,
          set_by_username = EXCLUDED.set_by_username,
          updated_at = NOW()
        RETURNING mood, updated_at
      )
      SELECT jsonb_build_object(
        'action', 'humor_definir',
        'mood', (SELECT mood FROM up),
        'updatedAt', (SELECT updated_at FROM up)
      ) AS result;
    `;
  }
  const payload = { guildId, userId, username, acao, humor };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'humor', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

// 5. Subcomando: afinidade
if (sub === 'afinidade') {
  const acao = String(opts.acao || 'ver');
  const estagio = String(opts.estagio || '').trim();
  const validStages = ['Conhecida', 'Amiga', 'Amiga Íntima', 'Confidente', 'Alma Gêmea'];

  if (acao === 'definir' && !validStages.includes(estagio)) {
    return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'afinidade', body, channels, sql: '', payloadB64: '', error: 'Estágio inválido. Use: ' + validStages.join(', '), webhookPatchUrl } }];
  }

  let sql = '';
  if (acao === 'ver') {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j)
      SELECT jsonb_build_object(
        'action', 'afinidade_ver',
        'current', (SELECT row_to_json(a) FROM usami_affinity a WHERE a.guild_id = (SELECT p.j->>'guildId' FROM p) ORDER BY a.updated_at DESC LIMIT 1)
      ) AS result;
    `;
  } else {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      up AS (
        INSERT INTO usami_affinity (guild_id, stage, set_by_user_id, set_by_username)
        SELECT p.j->>'guildId', p.j->>'estagio', p.j->>'userId', p.j->>'username' FROM p
        ON CONFLICT (guild_id) DO UPDATE SET
          stage = EXCLUDED.stage,
          set_by_user_id = EXCLUDED.set_by_user_id,
          set_by_username = EXCLUDED.set_by_username,
          updated_at = NOW()
        RETURNING stage, updated_at
      )
      SELECT jsonb_build_object(
        'action', 'afinidade_definir',
        'stage', (SELECT stage FROM up),
        'updatedAt', (SELECT updated_at FROM up)
      ) AS result;
    `;
  }
  const payload = { guildId, userId, username, acao, estagio };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'afinidade', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

// 6. Subcomando: sono
if (sub === 'sono') {
  const acao = String(opts.acao || 'ativar');

  if (!['ativar', 'desativar'].includes(acao)) {
    return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'sono', body, channels, sql: '', payloadB64: '', error: 'Ação deve ser ativar ou desativar', webhookPatchUrl } }];
  }

  let sql = '';
  if (acao === 'ativar') {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      up AS (
        INSERT INTO usami_sleep_mode (guild_id, channel_id, host_user_id, host_username, active, ends_at)
        SELECT p.j->>'guildId', p.j->>'channelId', p.j->>'userId', p.j->>'username', TRUE, NOW() + INTERVAL '30 minutes' FROM p
        ON CONFLICT (guild_id) DO UPDATE SET
          channel_id = EXCLUDED.channel_id,
          host_user_id = EXCLUDED.host_user_id,
          host_username = EXCLUDED.host_username,
          active = TRUE,
          ends_at = NOW() + INTERVAL '30 minutes',
          updated_at = NOW()
        RETURNING ends_at
      )
      SELECT jsonb_build_object(
        'action', 'sono_ativar',
        'endsAt', (SELECT ends_at FROM up),
        'durationMinutes', 30
      ) AS result;
    `;
  } else {
    sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      up AS (
        UPDATE usami_sleep_mode
        SET active = FALSE, updated_at = NOW()
        WHERE guild_id = (SELECT p.j->>'guildId' FROM p) AND active = TRUE
        RETURNING guild_id
      )
      SELECT jsonb_build_object(
        'action', 'sono_desativar',
        'deactivated', (SELECT COUNT(*) FROM up) > 0
      ) AS result;
    `;
  }
  const payload = { guildId, channelId, userId, username, acao };
  return [{ json: { mode: 'slash', commandName: 'usami', subcommand: 'sono', body, channels, sql, payloadB64: b64(payload), webhookPatchUrl } }];
}

throw new Error(`Subcomando /usami não reconhecido: ${sub}`);

const ctx = $('Roteador Usami e SQL').item.json;
const res = ($input.first().json && $input.first().json.result) || {};
const body = ctx.body || {};
const channels = ctx.channels || {};
const webhookPatchUrl = ctx.webhookPatchUrl || body.webhookPatchUrl || '';

const calls = [];

const addJsonCall = (method, url, payload, meta = {}) => {
  calls.push({
    json: {
      method,
      url,
      hasBody: true,
      bodyJson: JSON.stringify(payload),
      meta
    }
  });
};

// Se houve erro no roteador, retorna erro
if (ctx.error) {
  addJsonCall('PATCH', webhookPatchUrl, {
    content: `❌ ${ctx.error}`
  });
  return calls;
}

const sub = ctx.subcommand;

if (sub === 'chat') {
  // Para chat, apenas confirma que a mensagem foi logada
  // A resposta real vem do workflow de chat companion
  if (res.logged) {
    addJsonCall('PATCH', webhookPatchUrl, {
      content: `💬 Mensagem enviada para a Usami! ${res.logged.thread_created ? '(Thread criada para conversa longa)' : ''}`
    });
  } else {
    addJsonCall('PATCH', webhookPatchUrl, {
      content: '💬 Mensagem processada!'
    });
  }
}
else if (sub === 'status') {
  const srv = res.server || {};
  const mood = res.mood || {};
  const affinity = res.affinity || {};
  const sleep = res.sleepMode || {};
  const presence = res.presence || {};

  const moodLabels = {
    happy: 'Alegre ✨',
    tsundere: 'Tsundere 💢',
    surprised: 'Surpresa 💡',
    thinking: 'Pensativa 💭',
    neutral: 'Neutro',
    sad: 'Triste',
    angry: 'Brava 💢'
  };

  const affinityLabels = {
    'Conhecida': 'Conhecida 🤝',
    'Amiga': 'Amiga 💜',
    'Amiga Íntima': 'Amiga Íntima 💕',
    'Confidente': 'Confidente 🤫',
    'Alma Gêmea': 'Alma Gêmea 💖'
  };

  const fields = [
    { name: 'Mensagens contadas', value: String(srv.messages_count || 0), inline: true },
    { name: 'Comandos executados', value: String(srv.commands_count || 0), inline: true },
    { name: 'Membros acolhidos', value: String(srv.members_joined || 0), inline: true }
  ];

  if (mood.mood) {
    fields.push({ name: 'Humor atual', value: moodLabels[mood.mood] || mood.mood, inline: true });
  }
  if (affinity.stage) {
    fields.push({ name: 'Afinidade', value: affinityLabels[affinity.stage] || affinity.stage, inline: true });
  }
  if (sleep.active) {
    const endsUnix = sleep.ends_at ? Math.floor(new Date(sleep.ends_at).getTime() / 1000) : 0;
    fields.push({ name: 'Modo Sono', value: `Ativo até <t:${endsUnix}:R>`, inline: true });
  }
  if (presence.state) {
    fields.push({ name: 'Rich Presence', value: `${presence.details || presence.state}`, inline: true });
  }

  addJsonCall('PATCH', webhookPatchUrl, {
    embeds: [{
      title: '📊 Status da Usami Companion',
      color: 16735870,
      fields,
      footer: { text: `Guild: ${body.guildId || 'DM'} • Atualizado agora` }
    }]
  });
}
else if (sub === 'memoria') {
  if (res.action === 'memoria_ver') {
    const memories = Array.isArray(res.memories) ? res.memories : [];
    if (memories.length === 0) {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: '🧠 Nenhuma memória encontrada para este servidor.'
      });
    } else {
      const lines = memories.map(m => `• **${m.key}** — ${String(m.value).slice(0, 100)}${m.value.length > 100 ? '...' : ''} 
  \`${new Date(m.updated_at).toLocaleString('pt-BR')}\``).join('\n\n');
      addJsonCall('PATCH', webhookPatchUrl, {
        embeds: [{
          title: '🧠 Memórias de Longo Prazo',
          description: lines.slice(0, 4000),
          color: 2633026,
          footer: { text: `${memories.length} memória(s)` }
        }]
      });
    }
  } else if (res.action === 'memoria_limpar') {
    const deleted = Array.isArray(res.deleted) ? res.deleted : [];
    if (deleted.length > 0) {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: `🗑️ Memória **${deleted[0].key}** removida com sucesso!`
      });
    } else {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: 'Nenhuma memória encontrada com essa chave.'
      });
    }
  }
}
else if (sub === 'humor') {
  if (res.action === 'humor_ver') {
    const current = res.current || {};
    const moodLabels = {
      happy: 'Alegre ✨',
      tsundere: 'Tsundere 💢',
      surprised: 'Surpresa 💡',
      thinking: 'Pensativa 💭',
      neutral: 'Neutro',
      sad: 'Triste',
      angry: 'Brava 💢'
    };
    if (current.mood) {
      addJsonCall('PATCH', webhookPatchUrl, {
        embeds: [{
          title: '😊 Humor Atual da Usami',
          description: `**${moodLabels[current.mood] || current.mood}**
Definido por <@${current.set_by_user_id || 'sistema'}> em ${new Date(current.updated_at).toLocaleString('pt-BR')}`,
          color: 16754377
        }]
      });
    } else {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: 'A Usami ainda não tem humor definido. Use `/usami humor definir`!' 
      });
    }
  } else if (res.action === 'humor_definir') {
    const moodLabels = {
      happy: 'Alegre ✨',
      tsundere: 'Tsundere 💢',
      surprised: 'Surpresa 💡',
      thinking: 'Pensativa 💭',
      neutral: 'Neutro',
      sad: 'Triste',
      angry: 'Brava 💢'
    };
    addJsonCall('PATCH', webhookPatchUrl, {
      content: `😊 Humor da Usami alterado para **${moodLabels[res.mood] || res.mood}**!`
    });
  }
}
else if (sub === 'afinidade') {
  if (res.action === 'afinidade_ver') {
    const current = res.current || {};
    const affinityLabels = {
      'Conhecida': 'Conhecida 🤝',
      'Amiga': 'Amiga 💜',
      'Amiga Íntima': 'Amiga Íntima 💕',
      'Confidente': 'Confidente 🤫',
      'Alma Gêmea': 'Alma Gêmea 💖'
    };
    if (current.stage) {
      addJsonCall('PATCH', webhookPatchUrl, {
        embeds: [{
          title: '💜 Nível de Afinidade',
          description: `**${affinityLabels[current.stage] || current.stage}**
Definido por <@${current.set_by_user_id || 'sistema'}> em ${new Date(current.updated_at).toLocaleString('pt-BR')}`,
          color: 16735870
        }]
      });
    } else {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: 'Afinidade ainda não definida. Use `/usami afinidade definir`!' 
      });
    }
  } else if (res.action === 'afinidade_definir') {
    const affinityLabels = {
      'Conhecida': 'Conhecida 🤝',
      'Amiga': 'Amiga 💜',
      'Amiga Íntima': 'Amiga Íntima 💕',
      'Confidente': 'Confidente 🤫',
      'Alma Gêmea': 'Alma Gêmea 💖'
    };
    addJsonCall('PATCH', webhookPatchUrl, {
      content: `💜 Afinidade alterada para **${affinityLabels[res.stage] || res.stage}**!`
    });
  }
}
else if (sub === 'sono') {
  if (res.action === 'sono_ativar') {
    const endsUnix = res.endsAt ? Math.floor(new Date(res.endsAt).getTime() / 1000) : Math.floor(Date.now() / 1000 + 1800);
    addJsonCall('PATCH', webhookPatchUrl, {
      content: `🌙 Modo Sono ativado! A Usami vai fazer companhia por 30 minutos.`,
      embeds: [{
        title: '🌙 Modo Companhia para Dormir',
        description: `A Usami vai ficar por perto enviando mensagens suaves e reagindo até <t:${endsUnix}:R>.
Use \`/usami sono desativar\` para cancelar antes.`,
        color: 5763719,
        footer: { text: 'Duração: 30 minutos' }
      }]
    });
  } else if (res.action === 'sono_desativar') {
    if (res.deactivated) {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: '☀️ Modo Sono desativado. A Usami voltou ao normal!' 
      });
    } else {
      addJsonCall('PATCH', webhookPatchUrl, {
        content: 'O modo sono já estava desativado.' 
      });
    }
  }
}

return calls;
